      "kind": "writing",
      "title": "AI-generated Bermanisms",
      "slug": "ai_generated_bermanisms",
      "importance": 40,
      "metaDescription": "Jared \"Take A Load\" Goff or Jared \"Turn Your Head and\" Goff?",
      "homeCardText": "Jared \"Take A Load\" Goff --or--[br]Jared \"Turn Your Head and\" Goff?",
      "archiveCardText": "Jared \"Take A Load\" Goff --or--[br]Jared \"Turn Your Head and\" Goff?",
